// NODE 2: INPUT VALIDATION & SANITIZATION
// Validates that all measurements are positive numbers within realistic biological bounds

const item = $input.first().json;

// Extract measurements with flexible fallbacks
const sl = parseFloat(item["Sepal Length (cm)"] ?? item.sepal_length);
const sw = parseFloat(item["Sepal Width (cm)"] ?? item.sepal_width);
const pl = parseFloat(item["Petal Length (cm)"] ?? item.petal_length);
const pw = parseFloat(item["Petal Width (cm)"] ?? item.petal_width);

const errors = [];

if (isNaN(sl)) errors.push("Sepal Length must be a valid number.");
else if (sl <= 0) errors.push("Sepal Length must be greater than 0 cm.");
else if (sl > 25) errors.push("Sepal Length exceeds realistic biological range (max 25 cm).");

if (isNaN(sw)) errors.push("Sepal Width must be a valid number.");
else if (sw <= 0) errors.push("Sepal Width must be greater than 0 cm.");
else if (sw > 25) errors.push("Sepal Width exceeds realistic biological range (max 25 cm).");

if (isNaN(pl)) errors.push("Petal Length must be a valid number.");
else if (pl <= 0) errors.push("Petal Length must be greater than 0 cm.");
else if (pl > 25) errors.push("Petal Length exceeds realistic biological range (max 25 cm).");

if (isNaN(pw)) errors.push("Petal Width must be a valid number.");
else if (pw <= 0) errors.push("Petal Width must be greater than 0 cm.");
else if (pw > 25) errors.push("Petal Width exceeds realistic biological range (max 25 cm).");

const isValid = errors.length === 0;

return [{
  json: {
    isValid: isValid,
    errors: errors,
    sepal_length: sl,
    sepal_width: sw,
    petal_length: pl,
    petal_width: pw
  }
}];

// NODE 4: RESULT PROCESSING
// Extracts species prediction, confidence, submitted measurements, and formats a friendly report

const response = $input.first().json;

// Handle connection error or failure from API
if (response.error || response.status === 'error' || !response.predicted_species) {
  const errMsg = response.message || response.error || 'Failed to connect to Python Model API at http://127.0.0.1:5000.';
  return [{
    json: {
      success: false,
      title: '❌ Classification Failed',
      message: errMsg,
      recommendation: 'Ensure that the Python Prediction API (api/app.py) is running on port 5000.'
    }
  }];
}

const species = response.predicted_species;
const confidence = response.confidence_percentage ?? 100.0;
const measurements = response.submitted_measurements;
const explanation = response.explanation || '';

// Determine species emoji and icon
let emoji = '🌺';
if (species === 'Iris Setosa') emoji = '🌸';
else if (species === 'Iris Versicolor') emoji = '🌿';
else if (species === 'Iris Virginica') emoji = '🪻';

const displayHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; border: 2px solid #4CAF50; border-radius: 12px; background: #f9fbf9;">
  <h2 style="color: #2E7D32; text-align: center; margin-top: 0;">${emoji} Prediction Result: ${species}</h2>
  <hr style="border: none; border-top: 1px solid #C8E6C9; margin: 15px 0;">
  <p><strong>Predicted Species:</strong> <span style="font-size: 1.2em; color: #1B5E20; font-weight: bold;">${species}</span></p>
  <p><strong>Confidence Score:</strong> <span style="background: #E8F5E9; padding: 3px 8px; border-radius: 6px; font-weight: bold; color: #2E7D32;">${confidence}%</span></p>
  <p><strong>Machine Learning Model:</strong> Decision Tree Classifier (Scikit-Learn)</p>

  <h4 style="color: #2E7D32; margin-bottom: 8px;">Submitted Flower Measurements:</h4>
  <table style="width: 100%; border-collapse: collapse; margin-bottom: 15px;">
    <tr style="background: #E8F5E9;">
      <th style="border: 1px solid #C8E6C9; padding: 8px; text-align: left;">Measurement</th>
      <th style="border: 1px solid #C8E6C9; padding: 8px; text-align: right;">Value (cm)</th>
    </tr>
    <tr>
      <td style="border: 1px solid #C8E6C9; padding: 8px;">Sepal Length</td>
      <td style="border: 1px solid #C8E6C9; padding: 8px; text-align: right;">${measurements.sepal_length} cm</td>
    </tr>
    <tr style="background: #fdfdfd;">
      <td style="border: 1px solid #C8E6C9; padding: 8px;">Sepal Width</td>
      <td style="border: 1px solid #C8E6C9; padding: 8px; text-align: right;">${measurements.sepal_width} cm</td>
    </tr>
    <tr>
      <td style="border: 1px solid #C8E6C9; padding: 8px;">Petal Length</td>
      <td style="border: 1px solid #C8E6C9; padding: 8px; text-align: right;">${measurements.petal_length} cm</td>
    </tr>
    <tr style="background: #fdfdfd;">
      <td style="border: 1px solid #C8E6C9; padding: 8px;">Petal Width</td>
      <td style="border: 1px solid #C8E6C9; padding: 8px; text-align: right;">${measurements.petal_width} cm</td>
    </tr>
  </table>

  <div style="background: #E8F5E9; padding: 12px; border-left: 4px solid #4CAF50; border-radius: 4px; margin-bottom: 15px;">
    <strong>Botanical Explanation:</strong> ${explanation}
  </div>

  <p style="font-size: 0.85em; color: #666; text-align: center; margin-bottom: 0;">
    Orchestration: <strong>n8n Workflow Automation</strong> | Model Engine: <strong>Scikit-Learn DecisionTree</strong>
  </p>
</div>
`;

return [{
  json: {
    success: true,
    predicted_species: species,
    confidence_percentage: confidence,
    submitted_measurements: measurements,
    explanation: explanation,
    model: 'Decision Tree Classifier',
    html_response: displayHtml
  }
}];

// NODE 2b: FORMAT VALIDATION ERRORS
const item = $input.first().json;
const errorList = item.errors || ["Invalid measurement provided."];

const errorHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; border: 2px solid #E53935; border-radius: 12px; background: #FFEBEE;">
  <h2 style="color: #C62828; text-align: center; margin-top: 0;">⚠️ Input Validation Failed</h2>
  <hr style="border: none; border-top: 1px solid #FFCDD2; margin: 15px 0;">
  <p>Please correct the following errors and submit the form again:</p>
  <ul style="color: #B71C1C;">
    ${errorList.map(e => `<li>${e}</li>`).join('')}
  </ul>
  <p style="font-size: 0.9em; color: #555;">Note: All measurements must be positive numbers between 0.1 cm and 25.0 cm.</p>
</div>
`;

return [{
  json: {
    success: false,
    errors: errorList,
    html_response: errorHtml
  }
}];
